   "stem": "넙다리삼각을 열어 넙다리동맥과 그 가지를 노출한 해부 사진에서, 엉덩허리근과 두덩근 사이로 깊이 들어가며 번호핀 ①(▲)이 가리키는 동맥의 이름을 말하시오.",
