   "stem": "오른쪽 다리를 뒤에서 본 도해(왼쪽이 가쪽)에서 ①~④는 다리오금 마름모의 네 경계 근육, ⑤~⑦은 얕은 것부터 깊은 것 순서의 내용물, ⑧은 마름모의 가쪽 변을 따라 빠져나가는 신경이다. 각각을 한·영으로 답하고, 이어서 (가) 마름모의 바닥을 이루는 것 두 가지 (나) 무릎동맥 5가지 중 관절주머니를 뚫는 것 (다) ⑧이 감아도는 뼈 부위와 손상 시의 보행 이상을 답하시오.",
