   "stem": "오른심방을 열어 속면을 보여 주는 실사 사진이다. 번호핀 1–5가 가리키는 구조의 이름을 답하고, 4번이 발생학적으로 무엇과 무엇의 경계인지, 그리고 그 위끝에 무엇이 있는지 쓰시오.",
