   "examPhase": "tagging-1",
   "stem": "한쪽 얼굴이 처진 두 환자가 왔다. 한 사람은 이마에 주름을 잡을 수 있고 눈도 감기지만 입꼬리만 처졌고, 다른 한 사람은 이마 주름이 사라지고 눈이 감기지 않는다. (가) 각각 병변이 어디에 있는 마비인가. (나) 이마의 운동만 두 마비에서 다르게 나타나는 해부학적 이유를 설명하시오. (다) 말초성 마비에서 이마 처짐 말고 함께 나타날 수 있는 증상 세 가지를 각각 어느 가지가 막혀서 생기는지와 함께 답하시오. (라) 얼굴신경 줄기는 어느 구멍으로 머리뼈를 빠져나와 어디에서 다섯 가지로 갈라지는가. (마) 귀밑샘 수술에서 얼굴신경을 가장 먼저 찾아야 하는 이유와, 얼굴신경이 귀밑샘 속 세 구조 중 어느 층에 놓이는지 답하시오. (바) 말초성 마비 환자에게 가장 시급한 처치는 무엇이며 왜인가.",
   "choices": null,
   "answer": "(가) 이마가 보존된 쪽은 중추성(위운동신경세포) 마비로 병변이 반대쪽 대뇌겉질이나 겉질숨뇌로에 있고, 이마까지 마비된 쪽은 말초성(아래운동신경세포) 마비로 병변이 같은쪽 얼굴신경핵이나 그 이후의 신경 줄기에 있다 / (나) 얼굴신경핵에서 이마와 눈둘레근 위쪽을 담당하는 부분은 양쪽 대뇌겉질에서 겉질숨뇌섬유를 받지만 아래쪽 얼굴을 담당하는 부분은 반대쪽 겉질에서만 받는다. 그래서 한쪽 겉질이 망가져도 이마는 반대쪽 겉질이 대신 지배해 살아남는다 / (다) 눈을 감지 못하는 토안 lagophthalmos — 눈둘레근을 지배하는 광대가지와 관자가지 / 청각과민 hyperacusis — 등자근신경 n. to stapedius / 혀 앞 2/3의 미각 소실과 침 분비 감소 — 고삭신경 chorda tympani (그 밖에 눈물 분비 감소는 큰바위신경) / (라) 붓꼭지구멍 stylomastoid foramen 으로 나와 귀밑샘 속으로 들어간 뒤 위·아래 두 몸통으로 나뉘고 다시 거위발 pes anserinus 을 이루며 관자·광대·볼·아래턱모서리·목의 다섯 가지로 갈라진다 / (마) 귀밑샘을 뚫고 지나는 세 구조 중 얼굴신경이 가장 얕게 놓여 샘을 얕은엽과 깊은엽으로 나누기 때문에, 샘을 건드리기 전에 줄기를 먼저 찾아 보존하지 않으면 곧바로 손상되어 같은쪽 얼굴 전체가 말초성으로 마비된다 / (바) 눈을 감지 못해 각막이 마르고 노출성 각막염·궤양으로 시력을 잃을 수 있으므로 인공눈물과 연고, 안대나 눈꺼풀 폐쇄로 각막을 보호하는 것이 가장 시급하다",
   "explanation": "이 문항 하나에 4회차 얼굴 파트의 임상이 전부 들어 있다. 출발점은 **이마가 남으면 중추, 이마까지 가면 말초**라는 한 줄이고, 그 근거가 (나)의 이중 지배다. 얼굴신경핵의 위쪽 절반은 양쪽 겉질에서 입력을 받으므로 한쪽 겉질이 뇌졸중으로 망가져도 이마는 살아남는다. 반대로 신경 줄기 자체가 상하면 이중 지배고 뭐고 없이 그 신경이 가는 모든 근육이 죽는다. 그래서 진찰에서 가장 먼저 시키는 것이 ==이마에 주름 잡기와 눈 꽉 감기==다. (다)는 병변의 **높이**를 가늠하는 문제이기도 하다. 얼굴신경은 붓꼭지구멍을 나온 뒤로는 순수 운동신경이지만, 그 위 관자뼈 안에서는 큰바위신경(눈물)·등자근신경(청각)·고삭신경(미각·침)을 차례로 내준다. 따라서 미각까지 잃었다면 병변이 고삭신경 분지보다 위에 있다는 뜻이고, 얼굴 근육만 마비되었다면 붓꼭지구멍 아래일 가능성이 크다. 이런 식으로 증상 조합이 곧 국소진단이 된다. 벨마비 Bell palsy 는 이 말초성 마비의 가장 흔한 형태로, 대개 특발성이며 붓꼭지구멍 부근의 부종이 관여한다고 본다. (마)의 귀밑샘 순서는 **얕은 것부터 신–정–동**, 즉 ==얼굴신경 → 아래턱뒤정맥 → 바깥목동맥==이다. 얼굴신경이 가장 얕은 이유는 목적지가 피부밑 표정근육이기 때문이다. 이 순서 때문에 귀밑샘 종양이나 수술에서 가장 먼저 위험해지는 것이 얼굴신경이고, 수술에서는 귀구슬가리킴 tragal pointer, 두힘살근 뒤힘살, 붓꼭지구멍 같은 지표로 줄기를 먼저 확보한 다음 샘을 벗겨낸다. 참고로 귀밑샘 자체의 분비는 얼굴신경이 아니라 ==혀인두신경(IX)==이 귀신경절을 거쳐 맡으므로, 얼굴신경 손상으로 침이 마르는 것은 귀밑샘이 아니라 고삭신경이 가는 턱밑샘·혀밑샘 쪽이라는 점을 구분한다. (바)는 시험보다 진료에서 더 중요하다 — 마비 자체보다 각막이 먼저 상한다.",
