   "examPhase": "tagging-1",
   "stem": "4회차 실습주제의 마지막 세 부위를 정리하시오. (가) 입술의 주된 근육은 무엇이며, 입꼬리 가쪽에서 여러 표정근육이 모여 뭉치는 지점을 무엇이라 부르는가. (나) 윗입술과 아랫입술의 피부·점막 감각을 각각 어느 신경이 담당하며, 입술에 피가 도는 동맥은 무엇의 가지인가. (다) 바깥코에서 뼈로 된 부분과 연골로 된 부분을 나누고, 콧구멍 둘레의 모양을 만드는 연골의 이름을 답하시오. (라) 코등 위쪽과 코끝, 콧방울의 피부 감각을 각각 어느 삼차신경 가지가 담당하는지 답하고, 코끝의 감각이 임상에서 어떤 징후로 쓰이는지 설명하시오. (마) 귓바퀴는 어떤 연골로 되어 있으며 연골이 없는 부분은 어디인가. 바깥귀길은 가쪽과 안쪽이 각각 무엇으로 되어 있는가. (바) 귓바퀴의 감각을 나누어 맡는 신경을 앞·뒤로 나누어 답하고, 바깥귀길을 자극하면 기침이 나는 이유를 신경 이름을 들어 설명하시오.",
   "choices": null,
   "answer": "(가) 입둘레근 orbicularis oris m. 이며, 입꼬리 가쪽에서 근육들이 모이는 지점을 볼굴대 modiolus 라 한다(입둘레근·볼근·입꼬리당김근·큰광대근·입꼬리올림근·입꼬리내림근이 여기서 만난다) / (나) 윗입술은 위턱신경 V2 의 눈확아래신경 infraorbital n., 아랫입술은 아래턱신경 V3 의 턱끝신경 mental n. 이 담당한다. 동맥은 얼굴동맥 facial a. 의 가지인 위입술동맥과 아래입술동맥이다(운동은 얼굴신경 VII) / (다) 위쪽은 뼈로 코뼈 nasal bone 와 위턱뼈의 이마돌기가 이루고, 아래쪽은 연골로 가쪽코연골 lateral nasal cartilage, 큰코날개연골 major alar cartilage, 작은코날개연골, 그리고 가운데의 코중격연골 septal cartilage 이 이룬다. 콧구멍 둘레의 모양은 큰코날개연골이 안쪽다리와 가쪽다리로 감싸며 만든다 / (라) 코뿌리와 코등 위쪽은 눈신경 V1 의 도르래아래신경, 코끝과 코등 아래쪽은 같은 V1 의 앞벌집신경 anterior ethmoidal n. 에서 나온 코바깥가지 external nasal br., 콧방울은 위턱신경 V2 의 눈확아래신경이 담당한다. 코끝이 V1 영역이므로 눈신경 대상포진에서 코끝에 물집이 보이면 눈 침범 위험이 높다는 Hutchinson 징후로 쓰인다 / (마) 귓바퀴는 탄력연골 elastic cartilage 로 되어 있고 귓불 lobule 에는 연골이 없이 지방과 결합조직만 있다. 바깥귀길은 가쪽 3분의 1이 연골, 안쪽 3분의 2가 뼈(관자뼈)로 되어 있다 / (바) 귓바퀴의 앞·위쪽은 아래턱신경 V3 의 귓바퀴관자신경 auriculotemporal n., 뒤·아래쪽은 목신경얼기의 큰귓바퀴신경 great auricular n. (C2–C3)과 작은뒤통수신경 lesser occipital n. (C2)이 담당한다. 바깥귀길과 고막 일부에는 미주신경의 귓바퀴가지 auricular br. of vagus n., Arnold 신경 가 분포하므로 이곳을 자극하면 미주신경 반사로 기침이 난다",
   "explanation": "이 세 부위는 분량이 작아 넘어가기 쉽지만, 실습주제에 이름이 올라 있는 이상 예습시험 열 문제 안에 들어올 수 있다. 공통된 축은 **연골과 신경 경계** 둘이다. (가)의 볼굴대는 얼굴 가쪽에서 손으로 만져지는 단단한 매듭으로, 여러 표정근육이 힘을 주고받는 지점이다. 이 지점이 있기에 입꼬리를 여러 방향으로 정교하게 움직일 수 있고, 반대로 얼굴신경이 마비되면 볼굴대의 균형이 무너져 입꼬리가 건강한 쪽으로 끌려간다. 입술은 (나)에서 보듯 **위아래가 신경이 다르다** — 윗입술 V2, 아랫입술 V3 — 반면 근육의 운동은 위아래 모두 VII이 맡는다. 감각과 운동이 다른 신경이라는 얼굴의 원칙이 입술에서 가장 선명하게 드러나는 셈이다. (다)(라)의 코에서 요점은 **코끝은 뼈가 아니라 연골이고, 신경도 V2가 아니라 V1**이라는 두 가지다. 코를 위에서 아래로 훑으면 뼈에서 연골로 바뀌므로 코뼈 골절과 연골 손상이 나뉘는 지점이 생기고, 신경은 반대로 위와 코끝이 같은 V1으로 묶이고 그 사이의 콧방울만 V2로 끼어든다. 이 어긋남 때문에 코끝 감각이 진단에 쓰인다 — ==Hutchinson 징후==는 앞벌집신경이 눈신경의 가지라는 사실 하나에서 나온다. 코끝에 물집이 있다는 것은 이미 V1이 침범되었다는 뜻이고, 같은 V1이 각막도 담당하므로 눈을 봐야 한다. (마)(바)의 귀에서는 감각신경이 여러 개라는 점이 핵심이다. 귓바퀴 하나에 삼차신경(V3)·목신경(C2–C3)·미주신경이 함께 분포하는데, 이는 귀가 발생 과정에서 여러 인두굽이의 언덕이 합쳐져 만들어지기 때문이다. 그 흔적이 ==Arnold 신경==의 기침반사다. 귀를 후비다 기침이 나는 흔한 경험이 실은 미주신경 분포의 증거이고, 반대로 목이나 인두의 병이 귀 통증으로 느껴지는 연관통도 같은 이유로 설명된다. 턱뼈각과 귓바퀴 뒤가 모두 큰귓바퀴신경이라는 점은 0382의 (마)와 짝으로 외운다.",
